def inorder(root):
    return inorder(root.left) + [root.val] + inorder(root.right) if root else []

def memoize(func):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

