class TypistRanker {
public:
    std::vector<int> filterScores(const std::vector<int>& raw) {
        std::vector<int> out;
        std::copy_if(raw.begin(), raw.end(), std::back_inserter(out), [](int s) { return s >= 90; });
        return out;
    }
};

