use std::sync::Arc;
use std::sync::Mutex;

pub struct ConcurrentTracker {
    counter: Arc<Mutex<u64>>,
}

impl ConcurrentTracker {
    pub fn increment(&self) {
        let mut num = self.counter.lock().unwrap();
        *num += 1;
    }
}

