class MiniEmitter {
  constructor() { this.events = new Map(); }
  on(e, fn) {
    if (!this.events.has(e)) this.events.set(e, new Set());
    this.events.get(e).add(fn);
  }
  emit(e, ...args) {
    this.events.get(e)?.forEach(fn => fn(...args));
  }
}

function binarySearch(arr, x) {
  let l = 0, r = arr.length - 1;
  while (l <= r) {
    const m = (l + r) >> 1;
    if (arr[m] === x) return m;
    if (arr[m] < x) l = m + 1;
    else r = m - 1;
  }
  return -1;
}

